// usage: node num.mjs <file with one JSON string per line OR json array>
import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';
let raw = readFileSync(process.argv[2], 'utf8');
let inputs;
try { inputs = JSON.parse(raw); } catch { inputs = raw.split('\n').filter(l=>l.trim()).map(l=>JSON.parse(l)); }
const CONC = Number(process.argv[3] || 16);
const results = new Array(inputs.length);
let idx = 0;
function next(done) {
  if (idx >= inputs.length) return done();
  const i = idx++;
  execFile(EXE, ['--a', inputs[i]], { maxBuffer: 1 << 26, encoding: 'utf8' }, (err, so, se) => {
    results[i] = { i, out: so, err: se, rc: err ? (err.code ?? 1) : 0 };
    next(done);
  });
}
let live = CONC, fin = 0;
const finish = () => { if (++fin === live) {
  for (const r of results) {
    const line = JSON.stringify(inputs[r.i]) + '  ->  ' + JSON.stringify(r.out) + (r.rc? '  RC='+r.rc + ' ERR=' + JSON.stringify(r.err.slice(-200)) : '');
    process.stdout.write(line + '\n');
  }
} };
for (let k = 0; k < CONC; k++) next(finish);
EOF
